-- Live Wire - Viewpoint models: registers the model manifests of the Live Wire tiles
-- with Project Viewpoint (Viewpoint.ModelPacks.register(modId, path), path relative
-- to this mod; each modId + path pair is a separate pack). Does nothing when Viewpoint
-- is not active. The LiveWire Extended manifest is registered only when that sub-mod
-- is active. The models and the manifests are generated by
-- source/viewpoint/export_viewpoint.py.
local MOD_ID = "batman_LiveWireViewpoint"
local MANIFESTS = {
    { path = "media/livewire-viewpoint/livewire.properties" },
    { path = "media/livewire-viewpoint/extended.properties", requires = "batman_LiveWireExtended" },
}

local registered = {}

local function wanted(manifest)
    if not manifest.requires then return true end
    return LiveWire and LiveWire.Compat and LiveWire.Compat.isModActive(manifest.requires) or false
end

local function register()
    if not Viewpoint or not Viewpoint.ModelPacks then return end
    for _, manifest in ipairs(MANIFESTS) do
        if not registered[manifest.path] and wanted(manifest) then
            local ok, res = pcall(Viewpoint.ModelPacks.register, MOD_ID, manifest.path)
            if ok and res then
                registered[manifest.path] = true
            elseif not ok then
                print("[LiveWireViewpoint] registration failed for " .. manifest.path .. ": " .. tostring(res))
            end
        end
    end
end

Events.OnGameBoot.Add(register)
Events.OnGameStart.Add(register)
register()
